// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.concurrent.atomic.AtomicBoolean;

import org.junit.jupiter.api.Test;

class FrontierStatisticsHeapGovernorTest {

	@Test
	void queryLeasesRevokeBackgroundBeforeRefusingMemory() {
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(1_024L, 256L, 512L, 128L);
		AtomicBoolean builderReleased = new AtomicBoolean();
		try (FrontierStatisticsHeapGovernor.Lease metadata = governor.tryAcquire(
				FrontierStatisticsMemoryPurpose.MAPPED_METADATA, 128L)) {
			FrontierStatisticsHeapGovernor.Lease builder = governor.tryAcquire(
					FrontierStatisticsMemoryPurpose.BUILDER, 512L, () -> builderReleased.set(true));
			assertNotNull(builder);
			assertEquals(640L, governor.reservedBytes());

			try (FrontierStatisticsHeapGovernor.Lease query = governor.tryAcquire(
					FrontierStatisticsMemoryPurpose.QUERY, 400L)) {
				assertNotNull(query, "query borrowing must revoke background work before refusing memory");
				assertTrue(builderReleased.get());
				assertTrue(builder.revoked());
				assertTrue(builder.closed());
				assertEquals(0L, governor.reservedBytes(FrontierStatisticsMemoryPurpose.BUILDER));
				assertEquals(528L, governor.reservedBytes());
				assertNull(governor.tryAcquire(FrontierStatisticsMemoryPurpose.QUERY, 113L),
						"aggregate query scratch must not exceed its 512-byte ceiling");
				assertNull(governor.tryAcquire(FrontierStatisticsMemoryPurpose.COMPACTOR, 513L, () -> {
				}), "non-query work must preserve the guaranteed query reserve");
			}
			builder.close();
			assertEquals(128L, governor.reservedBytes());
		}
		assertEquals(0L, governor.reservedBytes());
	}

	@Test
	void limitsRejectOverflowAndInvalidEnvelopes() {
		assertThrows(IllegalArgumentException.class,
				() -> new FrontierStatisticsHeapGovernor(100L, 80L, 80L, 30L));
		assertThrows(IllegalArgumentException.class,
				() -> new FrontierStatisticsHeapGovernor(100L, 20L, 10L, 10L));
		FrontierStatisticsHeapGovernor governor = new FrontierStatisticsHeapGovernor(1_024L, 256L, 512L, 128L);
		assertNull(governor.tryAcquire(FrontierStatisticsMemoryPurpose.MAPPED_METADATA, Long.MAX_VALUE));
		assertThrows(IllegalArgumentException.class,
				() -> governor.tryAcquire(FrontierStatisticsMemoryPurpose.QUERY, -1L));
		assertThrows(IllegalArgumentException.class,
				() -> governor.tryAcquire(FrontierStatisticsMemoryPurpose.QUERY, 1L, () -> {
				}));
	}
}
